/**
 * The theme's canvas colours, without Electron. The preference itself is a
 * setting (core's THEME_SETTING, in the library's settings table); see
 * composition/theme-setting.ts.
 */
import type { ResolvedTheme } from '@taalcut/core';

/**
 * Window background per theme, copied from design/tokens/theme-meta.json
 * (generated by design/scripts/build-tokens.mjs). test/theme.test.ts fails if
 * the two drift apart.
 */
export const CANVAS: Readonly<Record<ResolvedTheme, string>> = {
  light: '#faf6f1',
  dark: '#181715',
};

export function canvasColour(dark: boolean): string {
  return dark ? CANVAS.dark : CANVAS.light;
}

/**
 * The glyphs of the controls the system draws over the window bar off a Mac (platform/frame.ts): ink-2, as the
 * bar's own icons, copied from design/tokens/tokens.json (test/theme.test.ts keeps them in step).
 */
export const SYMBOLS: Readonly<Record<ResolvedTheme, string>> = {
  light: '#48413b',
  dark: '#ceccc9',
};

/** The frame's colours for the theme that shows (platform/types.ts ChromeColours). */
export function chromeColours(dark: boolean): { background: string; symbols: string } {
  return { background: canvasColour(dark), symbols: dark ? SYMBOLS.dark : SYMBOLS.light };
}
